export const el2Tasks={"series": [{"id": "compare", "title": "Explain the circuit or response", "kind": "series", "type": "compare", "cases": [["0", "In a simple series loop current is…", ["The same through every component", "Used up by the first resistor", "Different because a resistor is drawn higher"], 0, "Charge does not accumulate in steady state."], ["1", "For two series resistors total resistance is…", ["Always less than either resistor", "R 1+R 2", "The same as the smaller resistor"], 1, "Series resistances add."], ["2", "A 6 V source across 10Ω and 20Ω gives current…", ["0.6 A", "3 A", "0.2 A"], 2, "Total 30Ω;6/30=0.2."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "series-data", "type": "numeric", "prompt": "Fresh circuit:5Ω and 15Ω in series across 10 V. Calculate source current.", "answer": 0.5, "unit": "A", "reasonChoices": ["10÷(5+15)", "10÷5+10÷15", "10×(5+15)"], "reason": 0, "why": "Use the correct relationship and paired readings."}, {"id": "model", "title": "Predict and compare every setting", "kind": "series-model", "type": "experiment", "experiment": "series", "why": "Use the selected circuit, supplied quantities and correct units."}], "parallel": [{"id": "compare", "title": "Explain the circuit or response", "kind": "parallel", "type": "compare", "cases": [["0", "Closed parallel branches between the same nodes have…", ["The same potential difference", "Always the same current", "No resistance"], 0, "Both branch ends connect to the same pair of nodes."], ["1", "The total source current equals…", ["Only the largest branch current", "The sum of branch currents", "Each branch current divided by their sum"], 1, "Charge is conserved at junctions."], ["2", "At 6 V,10Ω and 20Ω branches draw…", ["Both 0.9 A", "6 A and 12 A", "0.6 A and 0.3 A"], 2, "Each closed branch uses I=V/R."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "parallel-data", "type": "numeric", "prompt": "Fresh branch currents 0.3 A and 0.5 A join. Calculate source current.", "answer": 0.8, "unit": "A", "reasonChoices": ["0.3+0.5", "0.5−0.3", "0.3×0.5"], "reason": 0, "why": "Use the correct relationship and paired readings."}, {"id": "model", "title": "Predict and compare every setting", "kind": "parallel-model", "type": "experiment", "experiment": "parallel", "why": "Use the selected circuit, supplied quantities and correct units."}], "combinations": [{"id": "compare", "title": "Explain the circuit or response", "kind": "combinations", "type": "compare", "cases": [["0", "A series pair and a parallel pair differ because…", ["Their junctions create one path or alternative paths", "Only their colours differ", "Current is destroyed in one topology"], 0, "Trace electrical connections."], ["1", "For a group measurement the voltmeter goes…", ["In the source series path", "Across the whole group", "Directly in place of the ammeter"], 1, "Measure the same group whose total current is recorded."], ["2", "A fair topology comparison should keep…", ["All component values changing randomly", "Only the worksheet heading fixed", "The same resistors, sourcepd and comparable temperature"], 2, "Control alternative causes."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "combinations-data", "type": "numeric", "prompt": "Fresh series resistors 4Ω and 8Ω. Calculate equivalent resistance.", "answer": 12, "unit": "Ω", "reasonChoices": ["4+8", "8−4", "4×8"], "reason": 0, "why": "Use the correct relationship and paired readings."}, {"id": "model", "title": "Predict and compare every setting", "kind": "combinations-model", "type": "experiment", "experiment": "combinations", "why": "Use the selected circuit, supplied quantities and correct units."}], "thermistor": [{"id": "compare", "title": "Explain the circuit or response", "kind": "thermistor", "type": "compare", "cases": [["0", "For the NTC thermistor here, increasing temperature…", ["Decreases resistance", "Always increases resistance", "Leaves resistance fixed by definition"], 0, "Specify the component response."], ["1", "At fixedpd, decreasing thermistorR makes sensor current…", ["Disappear", "Increase", "Always decrease"], 1, "I=V/R."], ["2", "A thermostat uses the thermistor mainly to…", ["Provide all heater energy", "Guarantee a safe temperature without any circuit", "Sense temperature for a controller"], 2, "The controller interprets the sensing change."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "thermistor-data", "type": "numeric", "prompt": "Fresh thermistor measured at 2 V and 0.004 A. Calculate resistance.", "answer": 500, "unit": "Ω", "reasonChoices": ["2÷0.004", "2×0.004", "0.004÷2"], "reason": 0, "why": "Use the correct relationship and paired readings."}, {"id": "model", "title": "Predict and compare every setting", "kind": "thermistor-model", "type": "experiment", "experiment": "thermistor", "why": "Use the selected circuit, supplied quantities and correct units."}], "ldr": [{"id": "compare", "title": "Explain the circuit or response", "kind": "ldr", "type": "compare", "cases": [["0", "As light intensity increases an LDR’s resistance…", ["Decreases", "Must increase", "Is always zero"], 0, "State the required light-response trend."], ["1", "In darkness at fixedpd the sensor current is generally…", ["Larger becauseR is zero", "Smaller becauseR is higher", "Unrelated to resistance"], 1, "Use I=V/R."], ["2", "An LDR differs from an LED because it…", ["Always emits control light", "Has arrows for outgoing light only", "Changes resistance with received light"], 2, "Distinguish the sensor from an emitting component."]]}, {"id": "calculate", "title": "Calculate and explain", "kind": "ldr-data", "type": "numeric", "prompt": "Fresh LDR measured at 3 V and 0.001 A. Calculate resistance.", "answer": 3000, "unit": "Ω", "reasonChoices": ["3÷0.001", "3×0.001", "0.001÷3"], "reason": 0, "why": "Use the correct relationship and paired readings."}, {"id": "model", "title": "Predict and compare every setting", "kind": "ldr-model", "type": "experiment", "experiment": "ldr", "why": "Use the selected circuit, supplied quantities and correct units."}]};
export const tasksForEl2=k=>el2Tasks[k];export const validEl2=(c,a)=>a!==''&&a!==null&&a!==undefined&&Number(a)===c[3];export const numericEl2=(v,a)=>v!==''&&v!==null&&v!==undefined&&Number.isFinite(Number(v))&&Math.abs(Number(v)-a)<.001;export const advanceEl2=(r,n,v)=>Number.isInteger(n)&&n>=0&&n<r.length&&r[n]===v?n+1:n;
const positive=(...xs)=>xs.every(x=>Number.isFinite(x)&&x>0);
export function series(V,R1,R2){if(!positive(V,R1,R2))throw new RangeError('Positive finite voltage and resistances required.');let R=R1+R2,I=V/R;return{V,R1,R2,R,I,I1:I,I2:I,V1:I*R1,V2:I*R2};}
export function parallel(V,R1,R2){if(!positive(V,R1)||!(R2===null||positive(R2)))throw new RangeError('Use positive resistance or null for open branch.');let I1=V/R1,I2=R2===null?0:V/R2,I=I1+I2;return{V,R1,R2,I1,I2,I,R:V/I,open:R2===null};}
export function sensor(kind,stimulus,V){if(!['thermistor','ldr'].includes(kind)||!positive(V)||!Number.isFinite(stimulus)||(kind==='thermistor'?(stimulus<20||stimulus>60):(stimulus<0||stimulus>100)))throw new RangeError('Use the stated bounded sensor range and positivepd.');let R=kind==='thermistor'?1000/(1+.04*(stimulus-20)):10000/(1+.09*stimulus),I=V/R,on=kind==='thermistor'?stimulus<40:stimulus<50;return{kind,stimulus,V,R,I,mA:I*1000,on};}
export const experimentOptions={series:{a:[['6','6 V'],['12','12 V']],b:[['10','10 Ω'],['20','20 Ω']],labels:['Sourcepd (R₁=10Ω)','Second resistor'],unit:'A source current'},parallel:{a:[['6','6 V'],['12','12 V']],b:[['10','10 Ω'],['20','20 Ω'],['open','Branch2 open']],labels:['Sourcepd (R₁=10Ω)','Second branch'],unit:'A source current'},combinations:{a:[['series','Series pair'],['parallel','Parallel pair']],b:[['10','10 Ω'],['20','20 Ω']],labels:['Topology (source6V, R₁=10Ω)','Second resistor'],unit:'A source current'},thermistor:{a:[['20','20°C'],['60','60°C']],b:[['2','2 V'],['4','4 V']],labels:['Sensor temperature','Measuringpd'],unit:'mA sensor current'},ldr:{a:[['0','Dark: index0'],['100','Bright: index100']],b:[['2','2 V'],['4','4 V']],labels:['Light condition','Measuringpd'],unit:'mA sensor current'}};
export function experimentResult(k,a,b){let o=experimentOptions[k];if(!o||!o.a.some(x=>x[0]===String(a))||!o.b.some(x=>x[0]===String(b)))throw new RangeError('Choose stated settings.');if(k==='series'){let r=series(+a,10,+b);return{...r,topology:'series',value:r.I};}if(k==='parallel'){let r=parallel(+a,10,b==='open'?null:+b);return{...r,topology:'parallel',value:r.I};}if(k==='combinations'){let r=a==='series'?series(6,10,+b):parallel(6,10,+b);return{...r,topology:a,value:r.I};}let r=sensor(k,+a,+b);return{...r,value:r.mA};}
export const experimentCases=k=>experimentOptions[k].a.flatMap(([a])=>experimentOptions[k].b.map(([b])=>a+':'+b));export const experimentValid=(k,v)=>experimentCases(k).every(x=>v.observed?.includes(x))&&v.interpretation==='limited';
